 assert.equal(d.request.cmd,'diff -u -- '+d.old_path+' '+d.new_path);
 assert(Buffer.from(d.result.output,'utf8').equals(read(base+d.diff_path)));
 const a=read(d.old_path).toString('utf8'),b=read(d.new_path).toString('utf8');
 assert(a.endsWith('\n')&&b.endsWith('\n'));
 if(!d.result.output){assert.equal(d.result.exit_code,0);assert.equal(a,b);continue;}
 assert.equal(d.result.exit_code,1);
